-- Perfil, medidas corporales y objetivos de fuerza: equivalente en Postgres/Supabase de la migración EF "AddProfile".
-- Es idempotente: se puede volver a ejecutar sin duplicar nada.

create table if not exists "UserProfiles" (
  "Id" integer generated by default as identity primary key,
  "UserId" integer not null,
  "HeightCm" double precision null,
  "BirthDate" timestamp null,
  "Sex" varchar(10) null,
  "ActivityLevel" varchar(20) null,
  "Phase" varchar(20) not null,
  "PhaseStartDate" timestamp null,
  "TargetWeightKg" double precision null,
  "TargetDate" timestamp null,
  "Notes" varchar(2000) null,
  "UpdatedAt" timestamp not null
);
create unique index if not exists "IX_UserProfiles_UserId" on "UserProfiles" ("UserId");

create table if not exists "BodyMeasurements" (
  "Id" integer generated by default as identity primary key,
  "UserId" integer not null,
  "Date" timestamp not null,
  "WeightKg" double precision null,
  "BodyFatPct" double precision null,
  "WaistCm" double precision null,
  "ChestCm" double precision null,
  "HipCm" double precision null,
  "ArmCm" double precision null,
  "ThighCm" double precision null,
  "Notes" varchar(1000) null
);
create unique index if not exists "IX_BodyMeasurements_UserId_Date" on "BodyMeasurements" ("UserId", "Date");

create table if not exists "LiftGoals" (
  "Id" integer generated by default as identity primary key,
  "UserId" integer not null,
  "ExerciseName" varchar(200) not null,
  "HevyExerciseTemplateId" varchar(50) null,
  "TargetWeightKg" double precision not null,
  "TargetReps" integer not null,
  "TargetDate" timestamp null,
  "Notes" varchar(1000) null,
  "Achieved" boolean not null default false
);
create index if not exists "IX_LiftGoals_UserId" on "LiftGoals" ("UserId");

-- Como el resto de tablas: RLS activado y sin políticas, de modo que la API REST de Supabase (clave anónima) no ve nada.
-- La API de Compás se conecta con un rol propietario y no se ve afectada.
alter table "UserProfiles" enable row level security;
alter table "BodyMeasurements" enable row level security;
alter table "LiftGoals" enable row level security;
